    const [lastAccessedWorkspacePolicyID] = useOnyx(ONYXKEYS.LAST_ACCESSED_WORKSPACE_POLICY_ID);
    const [activeWorkspaceID, setActiveWorkspaceID] = useState<string | undefined>(lastAccessedWorkspacePolicyID ?? undefined);

    useEffect(() => {
        if (!lastAccessedWorkspacePolicyID) {
            return;
        }
        setActiveWorkspaceID(lastAccessedWorkspacePolicyID);
    }, [lastAccessedWorkspacePolicyID]);

    const selectWorkspace = useCallback((policyID: string | undefined) => {
        Onyx.set(ONYXKEYS.LAST_ACCESSED_WORKSPACE_POLICY_ID, policyID ?? null);
